// Formats the who_went_cold answer into a short radar list.
// Response shape (docs): { ok: true, result: { coldConversations: [...] } }
// Read-only: this workflow never sends a follow-up. Draft one yourself,
// or use the revive-cold-threads prompt recipe in ../recipes.
const first = $input.all()[0].json;
if (!first.ok) {
  return [{ json: { brief: 'HeyReagent call failed: ' + (first.message || first.error || 'unknown error') } }];
}
const cold = (first.result && first.result.coldConversations) || [];
if (cold.length === 0) {
  return [{ json: { brief: 'Cold radar: no conversations went cold this week.' } }];
}
const lines = cold.map((c, i) => {
  const who = c.profileUrl || c.name || JSON.stringify(c);
  return (i + 1) + '. ' + who;
});
return [{ json: { brief: 'Cold radar: ' + cold.length + ' conversations went quiet:\n' + lines.join('\n') } }];
